class ASTAttribute(ASTBaseBase):
    def describe_signature(self, signode: TextElement) -> None:
        raise NotImplementedError(repr(self))


class ASTCPPAttribute(ASTAttribute):
    def __init__(self, arg: str) -> None:
        self.arg = arg

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ASTCPPAttribute):
            return NotImplemented
        return self.arg == other.arg

    def __hash__(self) -> int:
        return hash(self.arg)

    def _stringify(self, transform: StringifyTransform) -> str:
        return f'[[{self.arg}]]'

    def describe_signature(self, signode: TextElement) -> None:
        signode.append(addnodes.desc_sig_punctuation('[[', '[['))
        signode.append(nodes.Text(self.arg))
        signode.append(addnodes.desc_sig_punctuation(']]', ']]'))


class ASTGnuAttribute(ASTBaseBase):
    def __init__(self, name: str, args: ASTBaseParenExprList | None) -> None:
        self.name = name
        self.args = args

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ASTGnuAttribute):
            return NotImplemented
        return self.name == other.name and self.args == other.args

    def __hash__(self) -> int:
        return hash((self.name, self.args))

    def _stringify(self, transform: StringifyTransform) -> str:
        if self.args:
            return self.name + transform(self.args)
        return self.name

def match(self, regex: re.Pattern[str]) -> bool:
    match = regex.match(self.definition, self.pos)
    if match is not None:
        self._previous_state = (self.pos, self.last_match)
        self.pos = match.end()
        self.last_match = match
        return True
    return False

def skip_string(self, string: str) -> bool:
    strlen = len(string)
    if self.definition[self.pos : self.pos + strlen] == string:
        self.pos += strlen
        return True
    return False

def skip_word(self, word: str) -> bool:
    return self.match(re.compile(r'\b%s\b' % re.escape(word)))

def skip_ws(self) -> bool:
    return self.match(_whitespace_re)

def skip_word_and_ws(self, word: str) -> bool:
    if self.skip_word(word):
        self.skip_ws()
        return True
    return False

def skip_string_and_ws(self, string: str) -> bool:
    if self.skip_string(string):
        self.skip_ws()
        return True
    return False

@property
def eof(self) -> bool:
    return self.pos >= self.end

@property
def current_char(self) -> str:
    try:
        return self.definition[self.pos]
    except IndexError:
        return 'EOF'

@property
def matched_text(self) -> str:
    if self.last_match is not None:
        return self.last_match.group()
    return ''

def read_rest(self) -> str:
    rv = self.definition[self.pos :]
    self.pos = self.end
    return rv

def assert_end(self, *, allowSemicolon: bool = False) -> None:
    self.skip_ws()
    if allowSemicolon:
        if not self.eof and self.definition[self.pos :] != ';':
            self.fail('Expected end of definition or ;.')
    else:
        if not self.eof:
            self.fail('Expected end of definition.')

